import loggingimport threadingfrom csv import excelfrom glob import magic_checkfrom logging import exception, errorfrom discord import Color, ClientExceptionfrom discord.utils import utcnowfrom yt_dlp import YoutubeDLimport discordfrom discord.ext import commandsfrom print_color import printfrom urllib import parse, requestimport reimport jsonimport osimport asynciofrom asyncio import run_coroutine_threadsafefrom cogs.JoinCommand import JoinCommandfrom utils.EmbedGeneratorUtil import EmbedGeneratorfrom utils.custom.errors.FingerBangThePoonTangBotError import BotNotInChannelError, BotAlreadyInChannelError, \    CouldNotConnectToChannelError, UserNotInChannelError, UnknownCommandFailureclass MusicCommands(commands.Cog):    def __init__(self, bot: commands.Bot):        self.bot = bot        self.logger = logging.getLogger('discord')        self.pause_embed_msg = None    def now_playing_embed(self, ctx: commands.Context, song):        embed1 = discord.Embed(title=f"▶️ Playing Song",                               description=f"[{song['title']}]({song['link']})\n{song['description']}",                               colour=Color.blue(), timestamp=utcnow())        embed1.set_footer(            text=f"This message was brought to you by {self.bot.user.name}'s Message Delivery System!",            icon_url=self.bot.user.avatar.url)        embed1.set_image(url=song['thumbnail'])        embed1.add_field(name="Title / Artist", value=song['title'])        embed1.add_field(name="Channel", value=song['channel_url'])        embed1.add_field(name="Added By", value=ctx.author.mention)        embed1.add_field(name="Video Duration", value=song['duration_string'])        embed1.add_field(name="Like Count", value=song['like_count'])        embed1.add_field(name="View Count", value=song['view_count'])        return embed1    async def join_VC(self, ctx: commands.Context, channel: discord.VoiceChannel):        """        TODO documentation        :param ctx:        :param channel:        :return:        """        id = int(ctx.guild.id)        if self.bot.vc[id] is None or not self.bot.vc[id].is_connected():            self.bot.vc[id] = await channel.connect()            if self.bot.vc[id] is None:                raise BotAlreadyInChannelError(error="I Am Already In A Voice Channel. You Can Move Me To Your Current Channel If You Wish!")    def extract_YT(self, url: str, msg_: discord.Message):        """        TODO documentation        :param url:        :param msg_:        :return:        """        link, thumbnail, source, title, description, duration, like_count, view_count, channel_url, msg = "", "", "", "", "", "", "", "", "", msg_        with (YoutubeDL(self.bot.YDL_OPTS) as ydl):            try:                info = ydl.extract_info(url, download=False)                link = info['webpage_url']                thumbnail = info['thumbnail']                source = info['url']                title = info['title']                description = info['description']                duration = info['duration_string']                msg = msg_                like_count, view_count, channel_url = info['like_count'], info['view_count'], info['channel_url']            except Exception as e:                print(e)                return False        return {            'link': link,            'thumbnail': thumbnail,            'source': source,            'title': title,            'description': description,            'duration_string': duration,            'like_count': like_count,            'view_count': view_count,            'channel_url': channel_url,            'msg': msg        }    def search_YT(self, search: str) -> str:        """        TODO documentation        :param search:        :return:        """        with YoutubeDL(self.bot.YDL_OPTS) as ydl:            songs = ydl.extract_info(f"ytsearch:{search}", download=False)            return songs['entries'][0]['webpage_url']    def play_next(self, ctx: commands.Context) -> None:        """        TODO documentation        :param ctx:        :return:        """        id = int(ctx.guild.id)        if not self.bot.is_playing[id]:            return        if self.bot.queueIndex[id] + 1 < len(self.bot.musicQueue[id]):            self.bot.is_playing[id] = True            self.bot.queueIndex[id] += 1            song = self.bot.musicQueue[id][self.bot.queueIndex[id]][0]            message = self.now_playing_embed(ctx, song)            coro1 = self.bot.change_presence(                activity=discord.Activity(type=discord.ActivityType.streaming, name=song['title'],                                          url=song['link']))            coro = song['msg'].edit(embed=message)            fut = run_coroutine_threadsafe(coro, self.bot.loop)            fut1 = run_coroutine_threadsafe(coro1, self.bot.loop)            self.bot.vc[id].play(discord.FFmpegPCMAudio(song['source'], **self.bot.FFMPEG_OPTS),                                 after=lambda e: self.play_next(ctx))            try:                fut.result()                fut1.result()            except Exception as e:                print(e)        else:            self.bot.queueIndex[id] += 1            self.bot.is_playing[id] = False            coro = self.bot.change_presence(activity=None)            fut = run_coroutine_threadsafe(coro, self.bot.loop)            try:                fut.result()            except Exception as e:                print(e)    async def play_music(self, ctx: commands.Context, msg: str = discord.Message) -> None:        """        TODO documentation        :param ctx:        :param msg:        :return:        """        id = int(ctx.guild.id)        if self.bot.queueIndex[id] < len(self.bot.musicQueue[id]):            self.bot.is_playing[id] = True            self.bot.is_paused[id] = False            await self.join_VC(ctx, self.bot.musicQueue[id][self.bot.queueIndex[id]][1])            song = self.bot.musicQueue[id][self.bot.queueIndex[id]][0]            message = self.now_playing_embed(ctx, song)            await self.bot.change_presence(                activity=discord.Activity(type=discord.ActivityType.streaming, name=song['title'],                                          url=song['link']))            if not msg:                await ctx.reply(embed=message)            await msg.edit(embed=message)            self.bot.vc[id].play(discord.FFmpegPCMAudio(song['source']), after=lambda e: self.play_next(ctx))        else:            if msg is not None:                await ctx.reply("There are no songs in queue to be played")                return            else:                await msg.edit("There are no songs in queue to be played.", embed=None)            self.bot.queueIndex[id] += 1            self.bot.is_playing[id] = False            await self.bot.change_presence(activity=None)    @commands.command(name="join", help="Joins the bot to a channel.")    async def join(self, ctx: commands.Context) -> None:        """        TODO documentation        :param ctx:        :return:        """        if ctx.author.voice:            user_channel = ctx.author.voice.channel            await self.join_VC(ctx, user_channel)    @commands.command(name="leave", help="Disconnects the bot to a channel.")    async def leave(self, ctx: commands.Context):        id = int(ctx.guild.id)        try:            self.bot.is_playing[id] = self.bot.is_paused[id] = False            self.bot.musicQueue[id] = []            self.bot.queueIndex[id] = 0            await self.bot.vc[id].disconnect()        except Exception as e:            print(e)    @commands.command(name="pause")    async def pause(self, ctx: commands.Context) -> None:        """        TODO documentation        :param ctx:        :return:        """        id = int(ctx.guild.id)        if not self.bot.vc[id]:            embed = EmbedGenerator(self.bot).generate_simple_message_embed(                description="You are not in a voice channel, so I can not pause!", colour=Color.dark_orange())            await ctx.reply(embed=embed, mention_author=False)        elif self.bot.is_playing[id]:            embed = EmbedGenerator(self.bot).generate_simple_message_embed(                description="Music paused successfully.", colour=Color.green())            self.pause_embed_msg = await ctx.reply(embed=embed, mention_author=False)            self.bot.is_playing[id] = False            self.bot.is_paused[id] = True            self.bot.vc[id].pause()    @commands.command(name="resume")    async def resume(self, ctx: commands.Context) -> None:        """        TODO documentation        :param ctx:        :return:        """        id = int(ctx.guild.id)        if len(self.bot.musicQueue[id]) == 0:            embed = EmbedGenerator(self.bot).generate_simple_message_embed(                description="There are no songs to be played in the queue!!", colour=Color.dark_orange())            await msg_.edit(embed=embed)        elif not self.bot.is_playing[id]:            if self.bot.musicQueue[id] is None or self.bot.vc[id] is None:                await self.play_music(ctx, msg_)            else:                self.bot.is_paused[id] = False                self.bot.is_playing[id] = True                self.bot.vc[id].resume()        elif not self.bot.vc[id]:            embed = EmbedGenerator(self.bot).generate_simple_message_embed(                description="You are not in a voice channel, so I can not resume!", colour=Color.dark_orange())            await ctx.reply(embed=embed, mention_author=False)        elif self.bot.is_paused[id]:            embed = EmbedGenerator(self.bot).generate_simple_message_embed(                description="Music paused successfully.", colour=Color.green())            self.pause_embed_msg = await ctx.reply(embed=embed, mention_author=False)            self.bot.is_playing[id] = True            self.bot.is_paused[id] = False            self.bot.vc[id].resume()        else:            pass    @commands.command(name="stop", help="Stops the currently playing audio, disconnects, then clears the queue.")    async def stop(self, ctx: commands.Context) -> None:        """        TODO documentation        :param ctx:        :return:        """        pass    @commands.command(name="play", help="Plays a song through the bot in a voice channel from a url or query string.")    async def play(self, ctx: commands.Context, *, query: str = commands.Parameter('search_query', description="The query to search youtube.", kind=commands.Parameter.POSITIONAL_OR_KEYWORD)) -> None:        """        TODO documentation        :param ctx:        :param query:        :return:        """        id = int(ctx.guild.id)        embed = EmbedGenerator(self.bot).generate_simple_message_embed(description=f"Searching for '{query}'! This may take some time.", colour=Color.blurple())        msg_ = await ctx.reply(embed=embed, mention_author=False)        try:            userChannel = ctx.author.voice.channel            song = await asyncio.to_thread(self.extract_YT, await asyncio.to_thread(self.search_YT, query), msg_)        except discord.ClientException:            embed = EmbedGenerator(self.bot).generate_simple_message_embed(                description="You are not in a voice channel, so I can not join!", colour=Color.dark_orange())            await msg_.edit(embed=embed)            return        if type(song) is type(True):            embed = EmbedGenerator(self.bot).generate_title_message_embed_with_footer(                title="📛 A Command Error Has Occurred 📛",                description="Could not download the song. Please try a different format!.", colour=Color.red(),                timestamp=True)            await msg_.edit(embed=embed)        else:            self.bot.musicQueue[id].append([song, userChannel])            embed = EmbedGenerator(self.bot).generate_simple_message_embed(                description=f"Successfully found {song['title']}!", colour=Color.green())            if not self.bot.is_playing[id]:                await msg_.edit(embed=embed)                await self.play_music(ctx, msg_)            else:                embed = EmbedGenerator(self.bot).generate_simple_message_embed(                    description="Added the song to the queue.!", colour=Color.green())                await msg_.edit(embed=embed)async def setup(bot: commands.Bot):    await bot.add_cog(MusicCommands(bot))